-- Synthetic records for the isolated development database. Safe to run again: it does nothing once the records are there.
-- It refuses to run on a database that holds any brand other than the two synthetic ones.
-- Run after the schema and every candidate in supabase/candidates (through 20261201). Run as the database owner.
-- Creates: 2 brands, 4 logins at example.test (no password: see auth-dev.sql), 6 products, 4 private shelves,
-- the Nexus v4 position list (P-01..P-66, STG-01, STG-02), 3 inbound shipments and 3 received pallets (one on HOLD).
-- Dates are relative to the day it runs: today, +3 days (date only), +5 days (10:00-11:00 Eastern appointment).
do $seed$
declare
  o1 constant uuid := '5a000000-0000-4000-8000-0000000000a1'; o2 constant uuid := '5a000000-0000-4000-8000-0000000000a2';
  uf constant uuid := '5b000000-0000-4000-8000-000000000002';
  s1 constant uuid := '5c000000-0000-4000-8000-000000001001'; s2 constant uuid := '5c000000-0000-4000-8000-000000001002'; s3 constant uuid := '5c000000-0000-4000-8000-000000001003';
  k1 constant uuid := '5d000000-0000-4000-8000-000000000001'; k2 constant uuid := '5d000000-0000-4000-8000-000000000002'; k5 constant uuid := '5d000000-0000-4000-8000-000000000005';
  hosted boolean := exists (select 1 from information_schema.columns where table_schema = 'auth' and table_name = 'users' and column_name = 'instance_id');
  u record; d date := current_date; r jsonb;
begin
  if exists (select 1 from orgs where id not in (o1, o2)) then raise exception 'This database holds brands other than the two synthetic ones. Nothing was written.'; end if;
  if exists (select 1 from orgs where id = o1) then raise notice 'Synthetic records are already here. Nothing was written.'; return; end if;
  if exists (select 1 from wms_pallets) or exists (select 1 from inventory_moves) then raise exception 'This database already holds pallets or stock. Nothing was written.'; end if;

  insert into orgs (id, name, slug, status, client_code) values (o1, 'Synthetic Records', 'synthetic-records', 'active', 'SYNR'), (o2, 'Synthetic Mailers', 'synthetic-mailers', 'active', 'SYNM');

  for u in select * from (values
      ('5b000000-0000-4000-8000-000000000001'::uuid, 'test-admin@example.test', 'shipbay_admin', 'Test Admin (synthetic)', null::uuid),
      ('5b000000-0000-4000-8000-000000000002'::uuid, 'test-floor@example.test', 'wms_employee', 'Test Floor (synthetic)', null),
      ('5b000000-0000-4000-8000-000000000003'::uuid, 'test-staff@example.test', 'shipbay_staff', 'Test Staff (synthetic)', null),
      ('5b000000-0000-4000-8000-000000000004'::uuid, 'test-client@example.test', 'client_admin', 'Test Client (synthetic)', o1)) v(id, email, role, full_name, org_id) loop
    if hosted then
      execute $q$insert into auth.users (instance_id, id, aud, role, email, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
          confirmation_token, recovery_token, email_change, email_change_token_new)
        values ('00000000-0000-0000-0000-000000000000', $1, 'authenticated', 'authenticated', $2, now(), '{"provider":"email","providers":["email"]}', $3, now(), now(), '', '', '', '')$q$
        using u.id, u.email, jsonb_strip_nulls(jsonb_build_object('role', u.role, 'full_name', u.full_name, 'org_id', u.org_id));
    else
      insert into auth.users (id, email, raw_user_meta_data) values (u.id, u.email, jsonb_strip_nulls(jsonb_build_object('role', u.role, 'full_name', u.full_name, 'org_id', u.org_id)));
    end if;
    -- the sign-up trigger makes the profile; this makes sure it carries the role whatever the trigger did
    insert into profiles (id, email, full_name, org_id, role) values (u.id, u.email, u.full_name, u.org_id, u.role)
    on conflict (id) do update set full_name = excluded.full_name, org_id = excluded.org_id, role = excluded.role, active = true;
  end loop;

  insert into skus (id, org_id, sku, name, barcode) values
    (k1, o1, 'SYN-LP-001', 'Synthetic LP, Black', '000000000011'), (k2, o1, 'SYN-LP-002', 'Synthetic LP, Clear', null),
    ('5d000000-0000-4000-8000-000000000003', o1, 'SYN-TEE-M', 'Synthetic Tee, M', null), ('5d000000-0000-4000-8000-000000000004', o2, 'SYN-MLR-L', 'Synthetic Mailer, Large', null),
    (k5, o2, 'SYN-MLR-S', 'Synthetic Mailer, Small', null), ('5d000000-0000-4000-8000-000000000006', o2, 'SYN-BOX-12', 'Synthetic Box, 12 in', null);

  insert into locations (code, zone, kind) select c, z, 'shelf' from (values ('A-01', 'A'), ('A-02', 'A'), ('A-03', 'A'), ('OB-01', 'open box')) v(c, z)
  where not exists (select 1 from locations l where l.code = v.c);

  -- the shared position list, exactly as the Nexus map (version 4) gives it
  r := nexus_registry_apply($snap${"version":4,"checksum":"be3cc8f3e9134cb4dfe7d3ac41773bc5d231ed56b4a42c05f5939467d67c8c4f","warehouse":"HILLSBOROUGH-TEST","locations":[{"id":"P-01","code":"P-01","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-02","code":"P-02","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-03","code":"P-03","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-04","code":"P-04","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-05","code":"P-05","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-06","code":"P-06","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-07","code":"P-07","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-08","code":"P-08","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-09","code":"P-09","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-10","code":"P-10","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-11","code":"P-11","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-12","code":"P-12","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-13","code":"P-13","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-14","code":"P-14","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-15","code":"P-15","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-16","code":"P-16","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-17","code":"P-17","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-18","code":"P-18","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-19","code":"P-19","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-20","code":"P-20","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-21","code":"P-21","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-22","code":"P-22","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-23","code":"P-23","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-24","code":"P-24","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-25","code":"P-25","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-26","code":"P-26","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-27","code":"P-27","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-28","code":"P-28","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-29","code":"P-29","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-30","code":"P-30","kind":"pallet","zone":"inbound","capacity":1,"status":"active","version":4},{"id":"P-31","code":"P-31","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-32","code":"P-32","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-33","code":"P-33","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-34","code":"P-34","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-35","code":"P-35","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-36","code":"P-36","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-37","code":"P-37","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-38","code":"P-38","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-39","code":"P-39","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-40","code":"P-40","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-41","code":"P-41","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-42","code":"P-42","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-43","code":"P-43","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-44","code":"P-44","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-45","code":"P-45","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-46","code":"P-46","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-47","code":"P-47","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-48","code":"P-48","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-49","code":"P-49","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-50","code":"P-50","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-51","code":"P-51","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-52","code":"P-52","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-53","code":"P-53","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-54","code":"P-54","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-55","code":"P-55","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-56","code":"P-56","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-57","code":"P-57","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-58","code":"P-58","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-59","code":"P-59","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-60","code":"P-60","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-61","code":"P-61","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-62","code":"P-62","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-63","code":"P-63","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-64","code":"P-64","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-65","code":"P-65","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"P-66","code":"P-66","kind":"pallet","zone":"outbound","capacity":1,"status":"active","version":4},{"id":"STG-01","code":"STG-01","kind":"floor","zone":"staging","capacity":null,"status":"active","version":4},{"id":"STG-02","code":"STG-02","kind":"floor","zone":"staging","capacity":null,"status":"active","version":4}]}$snap$::jsonb, false);
  if (select count(*) from locations where shared) <> 68 then raise exception 'Expected 68 shared positions, found %.', (select count(*) from locations where shared); end if;

  insert into inbound_shipments (id, org_id, reference, status, expected_at, pallets, cartons, origin, notes, approved_at, appt_starts_at, appt_ends_at) values
    (s1, o1, 'SYN-PO-1001', 'expected', d, 3, 30, 'Synthetic Vendor', 'SYNTHETIC', now(), null, null),
    (s2, o2, 'SYN-PO-1002', 'expected', d + 3, 2, 20, 'Synthetic Vendor', 'SYNTHETIC: date only, time not confirmed', now(), null, null),
    (s3, o1, 'SYN-PO-1003', 'expected', d + 5, 4, 40, 'Synthetic Vendor', 'SYNTHETIC: confirmed appointment', now(),
      ((d + 5) + time '10:00') at time zone 'America/New_York', ((d + 5) + time '11:00') at time zone 'America/New_York');
  insert into inbound_lines (inbound_id, sku_id, qty_expected) values (s1, k1, 1000), (s1, k2, 500), (s2, k5, 2000), (s3, k2, 800);

  -- received the way the floor does it, so labels, cartons, the receipt record and the activity log are the real thing
  perform set_config('request.jwt.claims', json_build_object('sub', uf, 'role', 'authenticated')::text, true);
  perform 1 from wms_receive_booking(s1, o1, jsonb_build_array(jsonb_build_object('sku', k1, 'cartons', 10, 'units_per_carton', 10)), 2, 'SYNTHETIC', 'syn-seed-1', 'partial', null);
  perform 1 from wms_receive_booking(s1, o1, jsonb_build_array(jsonb_build_object('sku', k2, 'cartons', 10, 'units_per_carton', 5)), 1, 'SYNTHETIC', 'syn-seed-2', 'hold', 'Synthetic: crushed corner');
  perform set_config('request.jwt.claims', '', true);

  if (select count(*) from wms_pallets) <> 3 or (select count(*) from wms_cartons) <> 30 or (select count(*) from wms_pallets where held) <> 1 or (select count(*) from inventory_moves) <> 0 then
    raise exception 'The synthetic receipt did not come out as expected. Nothing was written.';
  end if;
  raise notice 'Synthetic records written.';
end $seed$;
